#include <stdio.h>

void quick_sort(int fish[], int lo, int hi) {
    if (lo >= hi) {
        return;
    }

    int ruler = fish[hi];
    int small = lo;

    for (int i = lo; i < hi; i++) {
        if (fish[i] < ruler) {
            int t = fish[i];
            fish[i] = fish[small];
            fish[small] = t;
            small++;
        }
    }

    int t = fish[small];
    fish[small] = fish[hi];
    fish[hi] = t;

    quick_sort(fish, lo, small - 1);
    quick_sort(fish, small + 1, hi);
}

int main(void) {
    int fish[6] = {8, 3, 6, 1, 9, 2};
    quick_sort(fish, 0, 5);
    printf("尺子法：");
    for (int i = 0; i < 6; i++) {
        printf("%d ", fish[i]);
    }
    printf("\n");
    return 0;
}

