void merge(int fish[], int lo, int mid, int hi) {
    int tmp[64];
    int i = lo;
    int j = mid + 1;
    int k = 0;

    while (i <= mid && j <= hi) {
        if (fish[i] <= fish[j]) {
            tmp[k++] = fish[i++];
        } else {
            tmp[k++] = fish[j++];
        }
    }
    while (i <= mid) {
        tmp[k++] = fish[i++];
    }
    while (j <= hi) {
        tmp[k++] = fish[j++];
    }
    for (int t = 0; t < k; t++) {
        fish[lo + t] = tmp[t];
    }
}

